def insert(root, val):
    if root is None:
        return Node(val)
    if val < root.val:
        root.left = insert(root.left, val)
    else:
        root.right = insert(root.right, val)
    return root

def sorted_array_to_bst_brute(nums):
    root = None
    for v in nums:
        root = insert(root, v)          # inserting sorted values one by one
    return root

