def sorted_array_to_bst(nums):
    def build(l, r):
        if l > r:
            return None
        mid = (l + r) // 2                  # pick the middle as root
        root = TreeNode(nums[mid])
        root.left = build(l, mid - 1)         # left half becomes left subtree
        root.right = build(mid + 1, r)         # right half becomes right subtree
        return root
    return build(0, len(nums) - 1)

