    static TreeNode build(int l, int r) {
        if (l > r) return null;
        int mid = (l + r) / 2;                    // pick the middle as root
        TreeNode root = new TreeNode(nums[mid]);
        root.left = build(l, mid - 1);              // left half becomes left subtree
        root.right = build(mid + 1, r);              // right half becomes right subtree
        return root;
    }
